import { isEqual } from "es-toolkit";
import { assertEvent, assign, fromCallback, setup } from "xstate";

import { os } from "../runtime/bus";
import type { PayloadOf, ValueOf } from "../runtime/topics";

type PanelsMode = NonNullable<ValueOf<"panels.mode">>;

type Panel = NonNullable<Extract<PanelsMode, { ok: true }>["value"]>;

type PanelRequest = NonNullable<PayloadOf<"panels.mode.set">>;

const panelKey = (appId: string, name: string) => `${appId}:${name}`;

// Each app's named panels remember their own aside width, so a mode request
// reopens a panel at the width it was last dragged to. A size request records a
// new width and applies it live when that panel is the open aside, which lets an
// app resize with one event.
const applyPanelRequest = (
  sizes: Record<string, number>,
  current: Panel | null,
  value: PanelRequest | null,
): { sizes: Record<string, number>; panel: Panel | null } => {
  if (!value) return { sizes, panel: null };
  const key = panelKey(value.appId, value.name);
  if ("mode" in value) {
    const panel: Panel =
      value.mode === "aside"
        ? {
            appId: value.appId,
            name: value.name,
            mode: "aside",
            size: sizes[key],
          }
        : { appId: value.appId, name: value.name, mode: "full" };
    return { sizes, panel };
  }
  const opensThisAside =
    current?.mode === "aside" &&
    current.appId === value.appId &&
    current.name === value.name;
  return {
    sizes: { ...sizes, [key]: value.size },
    panel: opensThisAside ? { ...current, size: value.size } : current,
  };
};

const panelRequests = fromCallback(({ sendBack }) => {
  const controller = new AbortController();
  os.subscribe(
    "panels.mode.set",
    (message) =>
      sendBack({
        type: "panel.set",
        value: message.payload,
        appId: message.meta.appId,
      }),
    { signal: controller.signal },
  );
  return () => controller.abort();
});

type PanelsContext = {
  /** The one open panel. */
  panel: Panel | null;
  /** Panel widths, keyed by `${appId}:${name}`. */
  panelSizes: Record<string, number>;
};

// `appId` is stamped on by the bus, which is what the ownership guard trusts.
type PanelsEvent = {
  type: "panel.set";
  value: PanelRequest | null;
  appId: string;
};

/**
 * Owns the open panel and each app's remembered panel widths. Panels are
 * addressed by the app id the bus stamps on a request, so this stays independent
 * of the application list.
 */
export const panelsLogic = setup({
  types: {
    context: {} as PanelsContext,
    events: {} as PanelsEvent,
  },
  actors: { panelRequests },
  guards: {
    // An app drives only its own panel. The dock opens an app's panel by
    // speaking as that app, so the host needs no exception here.
    appOwnsPanel: ({ context, event }) => {
      assertEvent(event, "panel.set");
      return event.value
        ? event.value.appId === event.appId
        : context.panel?.appId === event.appId;
    },
  },
  actions: {
    publishPanel: ({ context, event }) => {
      assertEvent(event, "panel.set");
      const { panel } = applyPanelRequest(
        context.panelSizes,
        context.panel,
        event.value,
      );
      if (isEqual(panel, context.panel)) return;
      os.emit("panels.mode", { ok: true, value: panel });
    },
    storePanel: assign(({ context, event }) => {
      assertEvent(event, "panel.set");
      const { sizes, panel } = applyPanelRequest(
        context.panelSizes,
        context.panel,
        event.value,
      );
      return { panelSizes: sizes, panel };
    }),
  },
}).createMachine({
  id: "panels",
  invoke: { src: "panelRequests" },
  context: { panel: null, panelSizes: {} },
  on: {
    "panel.set": {
      guard: "appOwnsPanel",
      actions: [{ type: "publishPanel" }, { type: "storePanel" }],
    },
  },
});
